"""Apply Quantum Trader v3.5.44 on top of v3.5.43: MAZDOCK lot 225 / strikes
every 20 (Angel scrip master), journal shows the real auto-buy setup."""
import base64, hashlib, os, py_compile, sys, zlib
ITEMS = [{'f': 'backend/app/market/instruments.py', 'old': 'cb97e99b561bac7afe7110a24c181821e991ad3746ff0054511e176181d8987d', 'new': ''}, {'f': 'frontend/components/ReportsBoard.tsx', 'old': '5d2b2d385bde2c4f5bf127e8fefcb233e079773047c0a198daf9482455387eb8', 'new': ''}, {'f': 'backend/_smoke_v3543.py', 'old': 'd17fa93cfc8446efc01f8caf3e3dc17235f585ba9f0463f4e08fb7f74b809252', 'new': ''}]
bad = []
for it in ITEMS:
    p = it["f"]
    if not os.path.exists(p):
        bad.append(p + " (missing)"); continue
    h = hashlib.sha256(open(p, "rb").read().replace(b"\r\n", b"\n")).hexdigest()
    new = zlib.decompress(base64.b64decode(it["new"]))
    if h == hashlib.sha256(new).hexdigest():
        print("already v3.5.44:", p); sys.exit(1)
    if h != it["old"]:
        bad.append(p)
if bad:
    print("REFUSED - not the v3.5.43 version (apply qt_v3543_apply.py first):", bad); sys.exit(1)
for it in ITEMS:
    p = it["f"]
    if not os.path.exists(p + ".pre3544.bak"):
        os.replace(p, p + ".pre3544.bak")
    open(p, "wb").write(zlib.decompress(base64.b64decode(it["new"])))
    if p.endswith(".py"):
        py_compile.compile(p, doraise=True)
print("v3.5.44 applied OK (backups: *.pre3544.bak)")
